"use client";

import {
  lazy,
  Suspense,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type KeyboardEvent,
} from "react";
import { VideoPlayerContext } from "./video-player-context";
import { VideoPlayerStore } from "./video-player-store";
import { VideoControls, VideoStatus } from "./video-player-controls";
import {
  useVideoExpansion,
  useVideoReducedMotion,
} from "./video-player-motion";
import type { VideoPlayerProps } from "./video-player-types";

export type {
  VideoPlayerProps,
  VideoSource,
  VideoDrm,
  VideoQuality,
  VideoPlayerHandle,
  PlayerError,
} from "./video-player-types";
export { useVideoPlayer, useVideoState } from "./video-player-context";
export {
  VideoControls,
  VideoSeekbar,
  VideoPlayButton,
  VideoSettings,
  VideoVolume,
} from "./video-player-controls";
const Diagnostics = lazy(() => import("./video-player-diagnostics"));

export function VideoPlayer({
  src,
  source,
  type,
  engine = "shaka",
  poster,
  title = "Video",
  autoPlay = false,
  muted = false,
  loop = false,
  playing,
  onPlayingChange,
  controls = true,
  enableGooey = true,
  enableAnimations = true,
  enableDiagnostics = false,
  enablePictureInPicture = true,
  enableFullscreen = true,
  reducedMotion = false,
  onReady,
  onError,
  className = "",
  style,
  children,
}: VideoPlayerProps) {
  const [store] = useState(() => new VideoPlayerStore());
  const video = useRef<HTMLVideoElement>(null);
  const frame = useRef<HTMLDivElement>(null);
  const placeholder = useRef<HTMLDivElement>(null);
  const [expanded, setExpanded] = useState(false);
  const [fullscreen, setFullscreen] = useState(false);
  const [pip, setPip] = useState(false);
  const [support, setSupport] = useState({ fullscreen: false, pip: false });
  const [browserNotice, setBrowserNotice] = useState("");
  const reduced = useVideoReducedMotion(reducedMotion);
  const animated = enableAnimations && !reduced;
  const ready = useSyncExternalStore(
    store.subscribe,
    () => store.getSnapshot().ready,
    () => false,
  );
  const callbacks = useRef({
    playing,
    autoPlay,
    onReady,
    onError,
    onPlayingChange,
  });
  callbacks.current = { playing, autoPlay, onReady, onError, onPlayingChange };
  store.callbacks = {
    onReady: (handle) => {
      callbacks.current.onReady?.(handle);
      if (callbacks.current.playing ?? callbacks.current.autoPlay)
        void handle.play().catch(() => {});
    },
    onError: (error) => callbacks.current.onError?.(error),
    onPlayingChange: (value) => callbacks.current.onPlayingChange?.(value),
  };
  const mediaSource = useMemo(
    () => ({
      src: source?.src ?? src ?? "",
      type: source?.type ?? type,
      drm: source?.drm,
    }),
    [source?.src, source?.type, source?.drm, src, type],
  );
  const previousSource = useRef<string | null>(null);
  useEffect(() => {
    if (video.current) store.bind(video.current);
    return () => store.unbind();
  }, [store]);
  useEffect(() => {
    const sameSource = previousSource.current === mediaSource.src;
    previousSource.current = mediaSource.src;
    void store.load(mediaSource, engine, sameSource);
  }, [store, mediaSource, engine]);
  useEffect(() => {
    if (!ready || playing === undefined) return;
    if (playing) void store.play().catch(() => {});
    else store.pause();
  }, [playing, ready, store]);
  useEffect(() => {
    const el = video.current;
    if (!el) return;
    const doc = el.ownerDocument;
    setSupport({
      fullscreen: !!doc.fullscreenEnabled && !!frame.current?.requestFullscreen,
      pip: !!doc.pictureInPictureEnabled && !!el.requestPictureInPicture,
    });
    const full = () => setFullscreen(doc.fullscreenElement === frame.current);
    const picture = () => setPip(doc.pictureInPictureElement === el);
    const failure = () =>
      setBrowserNotice("Fullscreen was not available. Try cinematic mode.");
    doc.addEventListener("fullscreenchange", full);
    doc.addEventListener("fullscreenerror", failure);
    el.addEventListener("enterpictureinpicture", picture);
    el.addEventListener("leavepictureinpicture", picture);
    return () => {
      doc.removeEventListener("fullscreenchange", full);
      doc.removeEventListener("fullscreenerror", failure);
      el.removeEventListener("enterpictureinpicture", picture);
      el.removeEventListener("leavepictureinpicture", picture);
    };
  }, []);
  const closeExpanded = useCallback(() => setExpanded(false), []);
  useVideoExpansion(frame, placeholder, expanded, animated, closeExpanded);
  const togglePlayback = useCallback(() => {
    const next = store.getSnapshot().paused;
    if (callbacks.current.playing !== undefined)
      callbacks.current.onPlayingChange?.(next);
    else if (next) void store.play().catch(() => {});
    else store.pause();
  }, [store]);
  const toggleFullscreen = useCallback(() => {
    const el = frame.current;
    if (!el || !enableFullscreen || !support.fullscreen) return;
    setBrowserNotice("");
    void (
      el.ownerDocument.fullscreenElement === el
        ? el.ownerDocument.exitFullscreen()
        : el.requestFullscreen()
    ).catch(() =>
      setBrowserNotice("Fullscreen was not available. Try cinematic mode."),
    );
  }, [enableFullscreen, support.fullscreen]);
  const togglePip = useCallback(() => {
    const el = video.current;
    if (!el || !enablePictureInPicture || !support.pip) return;
    setBrowserNotice("");
    void (
      el.ownerDocument.pictureInPictureElement === el
        ? el.ownerDocument.exitPictureInPicture()
        : el.requestPictureInPicture()
    ).catch(() =>
      setBrowserNotice(
        "Picture-in-picture is unavailable for this video or browser.",
      ),
    );
  }, [enablePictureInPicture, support.pip]);
  const toggleExpanded = useCallback(() => {
    if (!fullscreen) setExpanded((value) => (value ? false : enableFullscreen));
  }, [fullscreen, enableFullscreen]);
  const context = useMemo(
    () => ({
      store,
      video,
      frame,
      animated,
      gooey: enableGooey && !reduced,
      expanded,
      fullscreen,
      pip,
      canExpand: enableFullscreen,
      canFullscreen: enableFullscreen && support.fullscreen,
      canPip: enablePictureInPicture && support.pip,
      togglePlayback,
      toggleExpanded,
      toggleFullscreen,
      togglePip,
    }),
    [
      store,
      animated,
      enableGooey,
      reduced,
      expanded,
      fullscreen,
      pip,
      enableFullscreen,
      enablePictureInPicture,
      support,
      togglePlayback,
      toggleExpanded,
      toggleFullscreen,
      togglePip,
    ],
  );
  const keyboard = (event: KeyboardEvent<HTMLDivElement>) => {
    if (
      event.defaultPrevented ||
      event.altKey ||
      event.ctrlKey ||
      event.metaKey ||
      event.nativeEvent.isComposing
    )
      return;
    const key = event.key.toLowerCase();
    const mediaShortcut = key === "m" || key === "f";
    if (event.target instanceof HTMLElement && event.target !== frame.current) {
      if (
        event.target.closest(
          'select,textarea,input:not([type="range"]),[contenteditable="true"]',
        )
      )
        return;
      if (!mediaShortcut && event.target.closest('input,button,[role="menu"]'))
        return;
    }
    if (mediaShortcut && event.repeat) {
      event.preventDefault();
      return;
    }
    const state = store.getSnapshot();
    switch (key) {
      case " ":
      case "k":
        togglePlayback();
        break;
      case "arrowleft":
        store.seek(state.time - 5);
        break;
      case "arrowright":
        store.seek(state.time + 5);
        break;
      case "arrowup":
        store.setVolume(state.volume + 0.05);
        break;
      case "arrowdown":
        store.setVolume(state.volume - 0.05);
        break;
      case "m":
        store.toggleMute();
        break;
      case "f":
        if (fullscreen) toggleFullscreen();
        else toggleExpanded();
        break;
      case "c":
        store.setTextTrack(
          state.captions.some((t) => t.active)
            ? "off"
            : (state.captions[0]?.id ?? "off"),
        );
        break;
      default:
        return;
    }
    event.preventDefault();
  };
  useEffect(() => {
    const el = frame.current;
    if (!el) return;
    const doc = el.ownerDocument;
    const hoverShortcut = (event: globalThis.KeyboardEvent) => {
      const key = event.key.toLowerCase();
      if (
        (key !== "m" && key !== "f") ||
        event.defaultPrevented ||
        event.altKey ||
        event.ctrlKey ||
        event.metaKey ||
        event.isComposing ||
        !el.matches(":hover")
      )
        return;
      // Focused controls use the React handler; only body focus needs hover routing.
      if (event.target !== doc.body && event.target !== doc.documentElement)
        return;
      event.preventDefault();
      if (event.repeat) return;
      if (key === "m") store.toggleMute();
      else if (fullscreen) toggleFullscreen();
      else toggleExpanded();
    };
    doc.addEventListener("keydown", hoverShortcut);
    return () => doc.removeEventListener("keydown", hoverShortcut);
  }, [store, fullscreen, toggleFullscreen, toggleExpanded]);
  return (
    <VideoPlayerContext.Provider value={context}>
      <div
        className={`w-full min-w-0 ${className}`}
        style={style}
        data-video-player=""
      >
        <div
          ref={placeholder}
          className="@container/player-layout relative aspect-video w-full"
        >
          <div
            ref={frame}
            popover="manual"
            tabIndex={0}
            role={expanded ? "dialog" : "region"}
            aria-modal={expanded || undefined}
            aria-label={`${title} video player`}
            onKeyDown={keyboard}
            className="@container absolute inset-0 isolate m-0 block h-full w-full overflow-visible rounded-[20px] border-0 bg-black p-0 text-white outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 [&::backdrop]:bg-black/70 [&::backdrop]:opacity-[var(--video-backdrop,0)]"
            style={{ display: "block", containerType: "size" }}
            data-expanded={expanded}
            data-motion={animated ? "full" : "reduced"}
          >
            <video
              ref={video}
              poster={source?.poster ?? poster}
              muted={muted}
              loop={loop}
              playsInline
              preload="metadata"
              aria-label={title}
              className="absolute inset-0 h-full w-full rounded-[inherit] object-cover"
            />
            <VideoStatus title={title} controls={controls} />
            {controls && <VideoControls />}
            {children}
            {expanded && !controls && (
              <button
                type="button"
                onClick={closeExpanded}
                className="absolute right-4 top-4 rounded-full bg-white/15 backdrop-blur-xl px-4 py-3 focus-visible:outline-2 focus-visible:outline-ring"
              >
                Close cinematic mode
              </button>
            )}
            <p
              role="status"
              className={
                browserNotice
                  ? "absolute left-4 top-4 max-w-[80%] rounded-lg bg-white/15 backdrop-blur-xl px-3 py-2 text-xs"
                  : "sr-only"
              }
            >
              {browserNotice}
            </p>
          </div>
        </div>
        {enableDiagnostics && (
          <Suspense
            fallback={
              <p className="p-3 text-xs text-muted-foreground">
                Loading diagnostics…
              </p>
            }
          >
            <Diagnostics format={mediaSource.type} src={mediaSource.src} />
          </Suspense>
        )}
      </div>
    </VideoPlayerContext.Provider>
  );
}

import type { CSSProperties, ReactNode } from "react";
import type shaka from "shaka-player";

export type VideoFormat = "hls" | "dash" | "mp4";
export type VideoEngine = "shaka" | "hls" | "native";
/** Shaka's installed configuration types, with partial nested configuration. */
export type VideoDrm = Omit<
  Partial<shaka.extern.DrmConfiguration>,
  "advanced"
> & {
  advanced?: Record<string, Partial<shaka.extern.AdvancedDrmConfiguration>>;
};
export interface VideoSource {
  src: string;
  type?: VideoFormat;
  poster?: string;
  drm?: VideoDrm;
}
export interface VideoQuality {
  id: string;
  label: string;
  width: number;
  height: number;
  bitrate: number;
  active: boolean;
}
export interface VideoTrack {
  id: string;
  label: string;
  language: string;
  active: boolean;
}
export interface PlayerError {
  code: string;
  category:
    "network" | "media" | "drm" | "permission" | "unsupported" | "unknown";
  message: string;
  fatal: boolean;
  retryable: boolean;
}
export interface PlaybackStats {
  width: number | null;
  height: number | null;
  estimatedBandwidth: number | null;
  variantBitrate: number | null;
  droppedFrames: number | null;
  loadLatency: number | null;
}
export interface PlayerCapabilities {
  quality: boolean;
  audio: boolean;
  captions: boolean;
  drm: boolean;
}
export type PlayerEvent =
  | { type: "loading" | "manifest" | "tracks" | "quality" | "recovery" }
  | { type: "buffering"; buffering: boolean }
  | { type: "error"; error: PlayerError };
export interface PlayerAdapter {
  readonly engine: VideoEngine;
  readonly capabilities: PlayerCapabilities;
  load(source: VideoSource, startTime?: number): Promise<void>;
  getQualities(): VideoQuality[];
  setQuality(id: string): void;
  getAudioTracks(): VideoTrack[];
  setAudioTrack(id: string): void;
  getTextTracks(): VideoTrack[];
  setTextTrack(id: string): void;
  getStats(): PlaybackStats;
  getSeekRange(): { start: number; end: number; live: boolean };
  destroy(): Promise<void> | void;
}
export interface VideoPlayerHandle {
  play(): Promise<void>;
  pause(): void;
  seek(time: number): void;
  setQuality(id: string): void;
  setAudioTrack(id: string): void;
  setTextTrack(id: string): void;
  setVolume(volume: number): void;
  toggleMute(): void;
  setPlaybackRate(rate: number): void;
  retry(): void;
}
export interface VideoPlayerProps {
  src?: string;
  source?: VideoSource;
  type?: VideoFormat;
  engine?: VideoEngine;
  poster?: string;
  title?: string;
  autoPlay?: boolean;
  muted?: boolean;
  loop?: boolean;
  /** Controlled intent. Pair with onPlayingChange; actual state follows media events. */
  playing?: boolean;
  onPlayingChange?: (playing: boolean) => void;
  controls?: boolean;
  enableGooey?: boolean;
  enableAnimations?: boolean;
  enableDiagnostics?: boolean;
  enablePictureInPicture?: boolean;
  enableFullscreen?: boolean;
  /** May force reduced motion, but never overrides the user's OS preference. */
  reducedMotion?: boolean;
  onReady?: (player: VideoPlayerHandle) => void;
  onError?: (error: PlayerError) => void;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}

import type {
  PlayerError,
  VideoEngine,
  VideoFormat,
  VideoQuality,
} from "./video-player-types";

export function formatVideoTime(value: number): string {
  if (!Number.isFinite(value) || value < 0) return "0:00";
  const seconds = Math.floor(value);
  const minutes = Math.floor(seconds / 60);
  return minutes >= 60
    ? `${Math.floor(minutes / 60)}:${String(minutes % 60).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`
    : `${minutes}:${String(seconds % 60).padStart(2, "0")}`;
}
export function detectVideoFormat(
  src: string,
  explicit?: VideoFormat,
): VideoFormat {
  if (explicit) return explicit;
  const path = src.split(/[?#]/)[0].toLowerCase();
  if (path.endsWith(".mpd")) return "dash";
  if (path.endsWith(".m3u8")) return "hls";
  return "mp4";
}
export function supportsSource(
  engine: VideoEngine,
  format: VideoFormat,
  drm = false,
) {
  if (drm && engine !== "shaka") return false;
  return (
    engine === "shaka" ||
    (engine === "hls" ? format === "hls" : format !== "dash")
  );
}
export function readRanges(ranges: TimeRanges): [number, number][] {
  return Array.from({ length: ranges.length }, (_, i) => [
    ranges.start(i),
    ranges.end(i),
  ]);
}
export function bufferAt(
  ranges: readonly (readonly [number, number])[],
  time: number,
) {
  const range = ranges.find(([start, end]) => time >= start && time <= end);
  return {
    ahead: range ? range[1] - time : 0,
    behind: range ? time - range[0] : 0,
  };
}
export function clampSeek(time: number, start: number, end: number) {
  return Number.isFinite(time) && end > start
    ? Math.min(end, Math.max(start, time))
    : start;
}
export function normalizeQualities(qualities: VideoQuality[]): VideoQuality[] {
  return [...qualities].sort(
    (a, b) => b.height - a.height || b.bitrate - a.bitrate,
  );
}
export function finite(value: number | undefined): number | null {
  return value !== undefined && Number.isFinite(value) ? value : null;
}
/** Deliberately discard engine messages, URLs, payloads and stack traces. */
export function playerError(error: unknown, fatal = true): PlayerError {
  const e = (
    typeof error === "object" && error !== null ? error : {}
  ) as Record<string, unknown>;
  const category =
    e.name === "NotAllowedError"
      ? "permission"
      : e.name === "NotSupportedError"
        ? "unsupported"
        : e.category === 1
          ? "network"
          : e.category === 6
            ? "drm"
            : e.category === 3 || e.category === 4 || e.category === 5
              ? "media"
              : "unknown";
  const messages = {
    permission: "Playback was blocked. Press play to try again.",
    unsupported: "This browser or playback engine cannot play this source.",
    network:
      "The video could not be downloaded. Check your connection and retry.",
    drm: "Protected playback could not start. Check device support and license configuration.",
    media: "This video could not be decoded or its manifest is invalid.",
    unknown: "The video could not start. Please try again.",
  };
  return {
    code: typeof e.code === "number" ? String(e.code) : category.toUpperCase(),
    category,
    message: messages[category],
    fatal,
    retryable: category !== "unsupported" && category !== "permission",
  };
}
export function unsupportedError(message: string): PlayerError {
  return {
    code: "UNSUPPORTED",
    category: "unsupported",
    message,
    fatal: true,
    retryable: false,
  };
}

import type {
  PlayerAdapter,
  PlayerCapabilities,
  PlayerError,
  PlayerEvent,
  PlaybackStats,
  VideoEngine,
  VideoPlayerHandle,
  VideoQuality,
  VideoSource,
  VideoTrack,
} from "./video-player-types";
import {
  bufferAt,
  clampSeek,
  detectVideoFormat,
  playerError,
  readRanges,
  supportsSource,
  unsupportedError,
} from "./video-player-utils";

export interface VideoState {
  ready: boolean;
  paused: boolean;
  buffering: boolean;
  ended: boolean;
  time: number;
  duration: number;
  volume: number;
  muted: boolean;
  rate: number;
  range: { start: number; end: number; live: boolean };
  buffered: [number, number][];
  engine: VideoEngine | null;
  capabilities: PlayerCapabilities;
  qualities: VideoQuality[];
  audio: VideoTrack[];
  captions: VideoTrack[];
  selectedQuality: string;
  error: PlayerError | null;
  notice: string;
}
export interface VideoDiagnostics {
  stats: PlaybackStats | null;
  bufferAhead: number;
  bufferBehind: number;
  stalls: number;
  bufferingSeconds: number;
  startupSeconds: number | null;
  latestError: PlayerError | null;
  events: { at: number; event: string; detail?: string }[];
}
const initialState = (): VideoState => ({
  ready: false,
  paused: true,
  buffering: false,
  ended: false,
  time: 0,
  duration: 0,
  volume: 1,
  muted: false,
  rate: 1,
  range: { start: 0, end: 0, live: false },
  buffered: [],
  engine: null,
  capabilities: { quality: false, audio: false, captions: false, drm: false },
  qualities: [],
  audio: [],
  captions: [],
  selectedQuality: "auto",
  error: null,
  notice: "",
});

/** One store per persistent video. All engine ownership changes pass through queue. */
export class VideoPlayerStore implements VideoPlayerHandle {
  private state = initialState();
  private diagnostics: VideoDiagnostics = {
    stats: null,
    bufferAhead: 0,
    bufferBehind: 0,
    stalls: 0,
    bufferingSeconds: 0,
    startupSeconds: null,
    latestError: null,
    events: [],
  };
  private listeners = new Set<() => void>();
  private metricsListeners = new Set<() => void>();
  private adapter: PlayerAdapter | null = null;
  private video: HTMLVideoElement | null = null;
  private queue: Promise<void> = Promise.resolve();
  private generation = 0;
  private source?: VideoSource;
  private requestedEngine: VideoEngine = "shaka";
  private previousVolume = 1;
  private lastTick = 0;
  private loadStarted = 0;
  private bufferStarted: number | null = null;
  private played = false;
  private metricsTimer?: ReturnType<typeof setInterval>;
  private removeMediaListeners?: () => void;
  callbacks: {
    onReady?: (handle: VideoPlayerHandle) => void;
    onError?: (error: PlayerError) => void;
    onPlayingChange?: (playing: boolean) => void;
  } = {};
  getSnapshot = () => this.state;
  getDiagnostics = () => this.diagnostics;
  subscribe = (fn: () => void) => {
    this.listeners.add(fn);
    return () => {
      this.listeners.delete(fn);
    };
  };
  subscribeDiagnostics = (fn: () => void) => {
    this.metricsListeners.add(fn);
    if (!this.metricsTimer)
      this.metricsTimer = setInterval(() => {
        if (typeof document !== "undefined" && !document.hidden) this.sample();
      }, 1000);
    return () => {
      this.metricsListeners.delete(fn);
      if (!this.metricsListeners.size) {
        clearInterval(this.metricsTimer);
        this.metricsTimer = undefined;
      }
    };
  };
  private patch(patch: Partial<VideoState>) {
    this.state = { ...this.state, ...patch };
    this.listeners.forEach((fn) => fn());
  }
  private log(event: string, detail?: string) {
    this.diagnostics = {
      ...this.diagnostics,
      events: [
        ...this.diagnostics.events.slice(-59),
        {
          at: Math.round(performance.now() - this.loadStarted),
          event,
          ...(detail ? { detail } : {}),
        },
      ],
    };
    this.metricsListeners.forEach((fn) => fn());
  }
  private setBuffering(buffering: boolean) {
    if (buffering === this.state.buffering) return;
    if (buffering) {
      this.bufferStarted = performance.now();
      if (this.played && !this.video?.paused && !this.video?.seeking)
        this.diagnostics = {
          ...this.diagnostics,
          stalls: this.diagnostics.stalls + 1,
        };
    } else if (this.bufferStarted !== null) {
      this.diagnostics = {
        ...this.diagnostics,
        bufferingSeconds:
          this.diagnostics.bufferingSeconds +
          (performance.now() - this.bufferStarted) / 1000,
      };
      this.bufferStarted = null;
    }
    this.patch({ buffering });
    this.log(buffering ? "Buffering started" : "Buffering ended");
  }
  private fail(error: PlayerError) {
    this.diagnostics = { ...this.diagnostics, latestError: error };
    this.log(
      error.fatal
        ? "Fatal playback error"
        : error.category === "network"
          ? "Network error"
          : "Playback warning",
      error.code,
    );
    if (error.fatal) {
      this.setBuffering(false);
      this.patch({ error });
    }
    this.callbacks.onError?.(error);
  }
  private refreshTracks() {
    if (!this.adapter) return;
    this.patch({
      qualities: this.adapter.getQualities(),
      audio: this.adapter.getAudioTracks(),
      captions: this.adapter.getTextTracks(),
    });
  }
  private engineEvent = (event: PlayerEvent) => {
    if (event.type === "error") {
      this.fail(event.error);
      return;
    }
    if (event.type === "buffering") {
      this.setBuffering(event.buffering);
      return;
    }
    if (event.type === "loading") this.log("Manifest loading");
    if (event.type === "manifest") this.log("Manifest parsed");
    if (event.type === "recovery") this.log("Recovery attempted");
    if (["manifest", "tracks", "quality"].includes(event.type))
      this.refreshTracks();
    if (event.type === "quality")
      this.log(
        "Quality switched",
        this.state.qualities.find((q) => q.active)?.label,
      );
  };
  bind(video: HTMLVideoElement) {
    this.video = video;
    const update = () => {
      const range = this.adapter?.getSeekRange() ?? {
        start: 0,
        end: 0,
        live: false,
      };
      this.patch({
        time: video.currentTime,
        duration: Number.isFinite(video.duration) ? video.duration : 0,
        paused: video.paused,
        ended: video.ended,
        volume: video.volume,
        muted: video.muted,
        rate: video.playbackRate,
        buffered: readRanges(video.buffered),
        range,
      });
    };
    const tick = () => {
      if (performance.now() - this.lastTick > 200) {
        this.lastTick = performance.now();
        update();
      }
    };
    const played = () => {
      this.setBuffering(false);
      if (!this.played)
        this.diagnostics = {
          ...this.diagnostics,
          startupSeconds: (performance.now() - this.loadStarted) / 1000,
        };
      this.played = true;
      this.patch({ error: null, notice: "" });
      this.log("Playback started");
      update();
    };
    const onPlay = () => {
      update();
      this.callbacks.onPlayingChange?.(true);
    };
    const onPause = () => {
      this.setBuffering(false);
      update();
      this.callbacks.onPlayingChange?.(false);
    };
    const listeners: [string, EventListener][] = [
      ["timeupdate", tick],
      ["progress", tick],
      ["durationchange", update],
      ["loadedmetadata", update],
      ["volumechange", update],
      ["ratechange", update],
      ["play", onPlay],
      ["pause", onPause],
      ["playing", played],
      ["ended", onPause],
      ["waiting", () => this.setBuffering(true)],
      [
        "seeking",
        () => {
          update();
          if (!video.paused) this.setBuffering(true);
        },
      ],
      [
        "seeked",
        () => {
          update();
          if (video.readyState >= 3) this.setBuffering(false);
        },
      ],
      [
        "canplay",
        () => {
          this.setBuffering(false);
          update();
        },
      ],
      [
        "error",
        () => {
          if (video.error && this.adapter?.engine === "native")
            this.fail(playerError({ category: 3, code: video.error.code }));
        },
      ],
    ];
    listeners.forEach(([name, fn]) => video.addEventListener(name, fn));
    this.removeMediaListeners = () =>
      listeners.forEach(([name, fn]) => video.removeEventListener(name, fn));
    update();
  }
  async load(source: VideoSource, engine: VideoEngine, resume = false) {
    const generation = ++this.generation;
    const position = resume ? this.video?.currentTime : undefined;
    const wasPlaying = resume && !this.video?.paused;
    this.source = source;
    this.requestedEngine = engine;
    this.queue = this.queue
      .then(async () => {
        // Teardown must settle before a different engine is constructed/attached.
        if (this.adapter) {
          const old = this.adapter;
          this.adapter = null;
          await old.destroy();
        }
        if (generation !== this.generation || !this.video) return;
        this.state = {
          ...initialState(),
          volume: this.video.volume,
          muted: this.video.muted,
          rate: this.video.playbackRate,
        };
        this.loadStarted = performance.now();
        this.played = false;
        this.bufferStarted = null;
        this.diagnostics = {
          stats: null,
          bufferAhead: 0,
          bufferBehind: 0,
          stalls: 0,
          bufferingSeconds: 0,
          startupSeconds: null,
          latestError: null,
          events: [],
        };
        this.patch({ buffering: true });
        this.bufferStarted = performance.now();
        if (
          !source.src.trim() ||
          !supportsSource(
            engine,
            detectVideoFormat(source.src, source.type),
            !!source.drm,
          )
        ) {
          this.fail(
            unsupportedError(
              "Choose Shaka for DASH or protected content; HLS.js accepts HLS sources only.",
            ),
          );
          return;
        }
        const emit = (event: PlayerEvent) => {
          if (generation === this.generation) this.engineEvent(event);
        };
        let factory: () => PlayerAdapter;
        if (engine === "shaka") {
          const { ShakaAdapter } = await import("./video-player-shaka");
          factory = () => new ShakaAdapter(this.video!, emit);
        } else if (engine === "hls") {
          const { createHlsAdapter } = await import("./video-player-hls");
          factory = () => createHlsAdapter(this.video!, emit);
        } else {
          const { NativeAdapter } = await import("./video-player-native");
          factory = () => new NativeAdapter(this.video!, emit);
        }
        if (generation !== this.generation || !this.video) return;
        const adapter = factory();
        this.adapter = adapter;
        this.patch({
          engine: adapter.engine,
          capabilities: adapter.capabilities,
        });
        // Do not block teardown behind network loading. destroy() cancels load().
        void adapter
          .load(source, position)
          .then(() => {
            if (generation !== this.generation) return;
            this.refreshTracks();
            this.patch({ ready: true });
            this.callbacks.onReady?.(this);
            if (wasPlaying) void this.play().catch(() => {});
          })
          .catch((error: unknown) => {
            if (generation === this.generation) this.fail(playerError(error));
          });
      })
      .catch((error: unknown) => {
        if (generation === this.generation) this.fail(playerError(error));
      });
