    this.removeMediaListeners?.();
    this.removeMediaListeners = undefined;
    this.video = null;
    clearInterval(this.metricsTimer);
    this.metricsTimer = undefined;
    this.queue = this.queue.then(async () => {
      if (this.adapter) {
        const old = this.adapter;
