      await this.video.play();
    } catch (error) {
      if (generation !== this.generation) return;
      const normalized = playerError(error, false);
      this.patch({ notice: normalized.message });
      this.fail(normalized);
      throw error;
    }
  }
  pause() {
    this.video?.pause();
  }
  seek(time: number) {
    if (!this.video || !this.adapter) return;
