export interface VideoPlayerContextValue {
  store: VideoPlayerStore;
  video: RefObject<HTMLVideoElement | null>;
  frame: RefObject<HTMLDivElement | null>;
  animated: boolean;
  gooey: boolean;
  expanded: boolean;
  fullscreen: boolean;
  pip: boolean;
  canFullscreen: boolean;
  canExpand: boolean;
  canPip: boolean;
