      initialized.current && animated ? videoFullscreenMotion.iconDuration : 0;
    initialized.current = true;
    const show = gsap.to(entering, {
      opacity: 1,
      scale: 1,
      duration,
      ease: videoFullscreenMotion.ease,
      overwrite: true,
    });
    const hide = gsap.to(leaving, {
      opacity: 0,
      scale: 0.6,
      duration,
      ease: videoFullscreenMotion.ease,
      overwrite: true,
