            </span>
          </div>
          <div className="min-h-0 overflow-y-auto overscroll-contain">
            {page === "main" && (
              <>
                <button
                  type="button"
                  role="menuitem"
                  disabled={
                    context.fullscreen ||
                    (!context.expanded && !context.canExpand)
                  }
                  onClick={() => choose(context.toggleExpanded)}
                  className="flex min-h-11 w-full items-center justify-between rounded-lg px-3 text-left text-xs hover:bg-white/10 focus-visible:bg-white/15 focus-visible:outline-none disabled:opacity-40"
                >
                  <span>
                    {context.expanded
                      ? "Exit cinematic mode"
                      : "Cinematic mode"}
                  </span>
                  <Expand className="size-3.5" />
                </button>
                <button
                  type="button"
                  role="menuitem"
                  disabled={!context.canFullscreen || context.expanded}
                  onClick={() => choose(context.toggleFullscreen)}
                  className="flex min-h-11 w-full items-center justify-between rounded-lg px-3 text-left text-xs hover:bg-white/10 focus-visible:bg-white/15 focus-visible:outline-none disabled:opacity-40"
                >
                  <span>
                    {context.fullscreen
                      ? "Exit browser fullscreen"
                      : "Browser fullscreen"}
                  </span>
                  <VideoFullscreenIcon
                    active={context.fullscreen}
                    animated={animated}
                  />
                </button>
                {(
                  [
                    [
                      "quality",
                      "Quality",
                      qualities.length
                        ? selected === "auto"
                          ? "Auto"
                          : qualities.find((q) => q.id === selected)?.label
                        : "Managed by browser",
                    ],
                    ["speed", "Playback speed", `${rate}×`],
                    [
                      "audio",
                      "Audio",
                      audio.find((t) => t.active)?.label ?? "Default",
                    ],
                    [
                      "captions",
                      "Captions",
                      captions.length
                        ? (captions.find((t) => t.active)?.label ?? "Off")
                        : "Unavailable",
                    ],
                  ] as const
                ).map(([key, label, value]) => (
                  <button
                    key={key}
                    type="button"
                    role="menuitem"
                    disabled={
                      (key === "quality" && !qualities.length) ||
                      (key === "audio" && !audio.length) ||
                      (key === "captions" && !captions.length)
                    }
                    onClick={() => setPage(key)}
                    className="flex min-h-11 w-full items-center justify-between gap-2 rounded-lg px-3 text-xs hover:bg-white/10 focus-visible:bg-white/15 focus-visible:outline-none disabled:opacity-40"
                  >
                    <span>{label}</span>
                    <span className="ml-auto max-w-28 truncate text-white/50">
                      {value}
                    </span>
                    <ChevronRight className="size-3" />
                  </button>
                ))}
                <div className="@min-[560px]/player-layout:hidden">
                  <button
                    type="button"
                    role="menuitem"
                    disabled={!context.canPip}
                    onClick={() => choose(context.togglePip)}
                    className="min-h-11 w-full rounded-lg px-3 text-left text-xs focus-visible:outline-2 focus-visible:outline-ring disabled:opacity-40"
                  >
                    Picture-in-picture{!context.canPip && " unavailable"}
                  </button>
                  <label className="flex min-h-11 items-center gap-3 px-3 text-xs">
                    Volume
                    <input
                      aria-label="Volume in settings"
                      type="range"
                      min={0}
                      max={1}
                      step={0.05}
                      defaultValue={store.getSnapshot().volume}
                      onChange={(e) => store.setVolume(Number(e.target.value))}
                      className="w-28 accent-white"
                    />
                  </label>
                </div>
                {range.live && (
                  <button
                    type="button"
                    role="menuitem"
                    onClick={() => choose(() => store.seek(range.end))}
                    className="min-h-11 w-full rounded-lg px-3 text-left text-xs focus-visible:outline-2 focus-visible:outline-ring"
                  >
                    Jump to live edge
                  </button>
                )}
              </>
            )}
            {page === "quality" && (
              <>
                {option(
                  "Auto · adaptive",
                  selected === "auto",
                  () => store.setQuality("auto"),
                  "auto",
                )}
                {qualities.map((q) =>
                  option(
                    `${q.label}${q.active ? " · active" : ""}`,
                    selected === q.id,
                    () => store.setQuality(q.id),
                    q.id,
                  ),
                )}
              </>
            )}
            {page === "speed" &&
              [0.5, 0.75, 1, 1.25, 1.5, 2].map((r) =>
                option(
                  `${r}×${r === 1 ? " · Normal" : ""}`,
                  rate === r,
                  () => store.setPlaybackRate(r),
                  String(r),
                ),
              )}
            {page === "audio" &&
              audio.map((t) =>
                option(
                  t.label,
                  t.active,
                  () => store.setAudioTrack(t.id),
                  t.id,
                ),
              )}
            {page === "captions" && (
              <>
                {option(
                  "Off",
                  !captions.some((t) => t.active),
                  () => store.setTextTrack("off"),
                  "off",
                )}
                {captions.map((t) =>
                  option(
                    t.label,
                    t.active,
                    () => store.setTextTrack(t.id),
                    t.id,
                  ),
                )}
              </>
            )}
          </div>
        </div>
      }
    </>
  );
}

export function VideoControls() {
  const context = useVideoPlayer();
  const { frame, animated, gooey } = context;
  const paused = useVideoState((s) => s.paused);
  const error = useVideoState((s) => s.error);
  const captions = useVideoState((s) => s.captions);
  const [active, setActive] = useState(true),
    [menu, setMenu] = useState(false),
    [scrubbing, setScrubbing] = useState(false);
  const [focused, setFocused] = useState(false);
  const dock = useRef<HTMLDivElement>(null),
    overlay = useRef<HTMLDivElement>(null);
  const seekSlot = useRef<HTMLDivElement>(null),
    timeline = useRef<HTMLDivElement>(null);
  const [timelineExpanded, setTimelineExpanded] = useState(false);
  const timelineEngaged = useRef(false);
  const pointerInControls = useRef(false);
  const touchInteraction = useRef(false);
  const timelineOpen = useRef(false);
  timelineOpen.current = timelineExpanded && !menu;
  const timelineDismiss = useRef(0);
  const cancelTimelineDismiss = useCallback(() => {
    timelineDismiss.current++;
  }, []);
  const dismissTimeline = useCallback(() => {
    const request = ++timelineDismiss.current;
    // Let the same pointer event update the shared hover region first. This
    // avoids gap flicker without holding the expanded state behind a timer.
    queueMicrotask(() => {
      if (
        request === timelineDismiss.current &&
        !timelineEngaged.current &&
        !pointerInControls.current &&
        (touchInteraction.current || !dock.current?.matches(":hover")) &&
        (touchInteraction.current ||
          !dock.current?.querySelector(":focus-visible"))
      )
        setTimelineExpanded(false);
    });
  }, []);
  const engageTimeline = useCallback(
    (engaged: boolean) => {
      timelineEngaged.current = engaged;
      cancelTimelineDismiss();
      if (engaged) setTimelineExpanded(true);
      else dismissTimeline();
    },
    [dismissTimeline, cancelTimelineDismiss],
  );
  useEffect(() => cancelTimelineDismiss, [cancelTimelineDismiss]);
  useEffect(() => {
    const el = frame.current;
    if (!el) return;
    const move = (event: PointerEvent) => {
      if (event.pointerType === "touch") {
        touchInteraction.current = true;
        pointerInControls.current = false;
        return;
      }
      touchInteraction.current = false;
      const rail = timeline.current?.getBoundingClientRect(),
        row = dock.current?.getBoundingClientRect();
      pointerInControls.current = !!(
        timelineOpen.current &&
        rail &&
        row &&
        event.clientX >= Math.min(rail.left, row.left) - 2 &&
        event.clientX <= Math.max(rail.right, row.right) + 2 &&
        event.clientY >= Math.min(rail.top, row.top) - 2 &&
        event.clientY <= Math.max(rail.bottom, row.bottom) + 2
      );
      if (pointerInControls.current) cancelTimelineDismiss();
      else if (timelineOpen.current) dismissTimeline();
    };
    const leave = () => {
      pointerInControls.current = false;
      dismissTimeline();
    };
    el.addEventListener("pointermove", move);
    el.addEventListener("pointerleave", leave);
    return () => {
      el.removeEventListener("pointermove", move);
      el.removeEventListener("pointerleave", leave);
    };
  }, [frame, dismissTimeline, cancelTimelineDismiss]);
  useVideoTimeline(
    overlay,
    dock,
    seekSlot,
    timeline,
    timelineExpanded && !menu,
    animated,
  );
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const pointerFocus = useRef(false);
  const visible =
    active ||
    paused ||
    !!error ||
    menu ||
    scrubbing ||
    focused ||
    timelineExpanded;
  useEffect(() => {
    const el = frame.current;
    if (!el) return;
    const reveal = (event?: PointerEvent) => {
      setActive(true);
      clearTimeout(timer.current);
      if (event?.pointerType === "touch")
        timer.current = setTimeout(() => setActive(false), 2400);
    };
    const leave = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setActive(false), 120);
    };
    const focus = () => {
      setFocused(
        !pointerFocus.current &&
          (el.matches(":focus-visible") ||
            !!el.querySelector(":focus-visible")),
      );
      setActive(true);
    };
    const pointerDown = (event: PointerEvent) => {
      touchInteraction.current = event.pointerType === "touch";
      pointerFocus.current = true;
      setFocused(false);
      reveal(event);
    };
    const keyboard = () => {
      touchInteraction.current = false;
      pointerFocus.current = false;
      if (el.contains(el.ownerDocument.activeElement)) setFocused(true);
    };
    const blur = (e: FocusEvent) => {
      if (!(e.relatedTarget instanceof Node) || !el.contains(e.relatedTarget))
        setFocused(false);
    };
    el.addEventListener("pointerenter", reveal);
    el.addEventListener("pointermove", reveal);
    el.addEventListener("pointerdown", pointerDown, true);
    el.addEventListener("pointerleave", leave);
    el.addEventListener("focusin", focus);
    el.addEventListener("focusout", blur);
    el.ownerDocument.addEventListener("keydown", keyboard, true);
    if (!el.matches(":hover"))
      timer.current = setTimeout(() => setActive(false), 2400);
    return () => {
      clearTimeout(timer.current);
      el.removeEventListener("pointerenter", reveal);
      el.removeEventListener("pointermove", reveal);
      el.removeEventListener("pointerdown", pointerDown, true);
      el.removeEventListener("pointerleave", leave);
      el.removeEventListener("focusin", focus);
      el.removeEventListener("focusout", blur);
      el.ownerDocument.removeEventListener("keydown", keyboard, true);
    };
  }, [frame]);
  useLayoutEffect(() => {
    if (!overlay.current) return;
    const tween = gsap.to(overlay.current, {
      opacity: visible ? 1 : 0,
      y: visible ? 0 : 8,
      duration: animated ? 0.32 : 0,
      ease: "power3.out",
      overwrite: true,
    });
    return () => {
      tween.kill();
    };
  }, [visible, animated]);
  return (
    <div
      ref={overlay}
      data-timeline-expanded={timelineExpanded && !menu}
      aria-hidden={!visible}
      inert={!visible}
      className="absolute inset-x-0 bottom-0 z-20 rounded-b-[inherit] bg-gradient-to-t from-black/65 to-transparent px-3 pb-3 pt-12 @min-[640px]/player-layout:px-8 @min-[640px]/player-layout:pb-5"
      style={{ pointerEvents: "none" }}
    >
      <div
        ref={dock}
        data-video-dock
        onPointerEnter={cancelTimelineDismiss}
        onPointerLeave={dismissTimeline}
        onBlur={dismissTimeline}
        style={{ pointerEvents: "none" }}
        className="relative z-20 flex flex-nowrap items-center gap-x-1"
      >
        <GooeySurface
          host={dock}
          menu={menu}
          animated={animated}
          enabled={gooey}
        />
        <div
          data-controls-group
          className="relative flex shrink-0 items-center"
          style={{ pointerEvents: visible ? "auto" : "none" }}
        >
          <VideoPlayButton />
          <VideoVolume />
          <VideoTime />
        </div>
        <div ref={seekSlot} aria-hidden className="mx-1 h-8 min-w-0 flex-1" />
        <div
          data-controls-group
          className="ml-auto flex shrink-0 items-center @min-[640px]/player-layout:ml-0"
          style={{ pointerEvents: visible ? "auto" : "none" }}
        >
          <span className="hidden @min-[640px]/player-layout:contents">
            <VideoTime remaining />
          </span>
          {captions.length > 0 && (
            <VideoButton
              label={
                captions.some((t) => t.active)
                  ? "Turn captions off"
                  : "Turn captions on"
              }
              className="hidden @min-[640px]/player-layout:inline-flex"
              aria-pressed={captions.some((t) => t.active)}
              onClick={() =>
                context.store.setTextTrack(
                  captions.some((t) => t.active) ? "off" : captions[0].id,
                )
              }
            >
              <Captions />
            </VideoButton>
          )}
          <VideoButton
            label={
              context.pip
                ? "Exit picture-in-picture"
                : context.canPip
                  ? "Picture-in-picture"
                  : "Picture-in-picture unavailable"
            }
            disabled={!context.canPip}
            className="hidden @min-[560px]/player-layout:inline-flex"
            onClick={context.togglePip}
          >
            <PictureInPicture2 />
          </VideoButton>
          <VideoSettings onOpenChange={setMenu} />
          <VideoFullscreenButton />
        </div>
      </div>
      <div
        ref={timeline}
        data-video-timeline
        className="absolute z-10"
        style={{ pointerEvents: visible ? "auto" : "none" }}
      >
        <VideoSeekbar
          onScrubbingChange={setScrubbing}
          onEngagementChange={engageTimeline}
        />
      </div>
    </div>
  );
}

export function VideoStatus({
  title,
  controls,
}: {
  title: string;
  controls: boolean;
}) {
  const { store, togglePlayback, animated } = useVideoPlayer();
  const paused = useVideoState((s) => s.paused),
    buffering = useVideoState((s) => s.buffering),
    error = useVideoState((s) => s.error),
    notice = useVideoState((s) => s.notice),
    ready = useVideoState((s) => s.ready);
  if (error)
    return (
      <div className="absolute inset-0 z-30 flex flex-col items-center justify-center gap-3 rounded-[inherit] bg-black/60 backdrop-blur-xl px-6 text-center">
        <p role="alert" className="max-w-sm text-sm">
          {error.message}
        </p>
        {error.retryable && (
          <button
            type="button"
            onClick={() => store.retry()}
            className="min-h-11 rounded-full border border-white/25 px-5 text-xs focus-visible:outline-2 focus-visible:outline-ring"
          >
            Retry video
          </button>
        )}
      </div>
    );
  return (
    <>
      {controls && (
        <button
          type="button"
          aria-label={`${paused ? "Play" : "Pause"} ${title}`}
          disabled={!ready}
          onClick={togglePlayback}
          className="absolute inset-0 z-10 rounded-[inherit] bg-transparent outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
        />
      )}
      {buffering && (
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
          <span
            role="status"
            className="flex items-center gap-2 rounded-full bg-white/15 backdrop-blur-xl px-4 py-2 text-xs"
          >
            <LoaderCircle
              className={`size-4 ${animated ? "animate-spin" : ""}`}
            />
            Loading video
          </span>
        </div>
      )}
      <p
        role="status"
        className={
          notice
            ? "absolute left-4 top-4 z-30 rounded-lg bg-white/15 backdrop-blur-xl px-3 py-2 text-xs"
            : "sr-only"
        }
      >
        {notice}
      </p>
    </>
  );
}

"use client";
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type RefObject,
} from "react";
import { gsap } from "gsap";
import { CustomEase } from "gsap/CustomEase";

gsap.registerPlugin(CustomEase);
// Slow departure, decisive middle, long settle. Geometry and icons use
// the same curve at different durations.
export const videoFullscreenMotion = {
  duration: 0.9,
  iconDuration: 0.45,
  ease: CustomEase.create("cavemio-video-fullscreen", "0.7,0,0.16,1"),
};
// Use the same 300ms curve for entry and exit, without a hover-out hold.
const timelineEase = CustomEase.create(
  "cavemio-video-timeline",
  "0.25,0.1,0.35,1",
);

/** Keep a single seek input while its measured slot opens into a separate row. */
export function useVideoTimeline(
  overlay: RefObject<HTMLDivElement | null>,
  dock: RefObject<HTMLDivElement | null>,
  slot: RefObject<HTMLDivElement | null>,
  timeline: RefObject<HTMLDivElement | null>,
  expanded: boolean,
  animated: boolean,
) {
  const state = useRef({ progress: 0 });
  useLayoutEffect(() => {
    const host = overlay.current,
      controls = dock.current,
      placeholder = slot.current,
      surface = timeline.current;
    if (!host || !controls || !placeholder || !surface) return;
    const geometry = {
      left: 0,
      top: 0,
      width: 0,
      fullLeft: 0,
      fullWidth: 0,
      lift: 44,
      height: 44,
      track: 28,
    };
    const render = () => {
      // Keep the rail's center anchored. Its
      // width, thickness and controls share exactly one progress value, with
      // no lead or delayed interval in either direction. Controls stay above
      // the decorative rail while their hit targets pass through its bounds.
      const p = state.current.progress;
      const mix = (a: number, b: number) => a + (b - a) * p;
      gsap.set(controls, {
        y: -geometry.lift * (1 - p),
      });
      gsap.set(surface, {
        autoRound: false,
        left: mix(geometry.left, geometry.fullLeft),
        top: geometry.top - geometry.lift + 16 - mix(32, geometry.height) / 2,
        width: mix(geometry.width, geometry.fullWidth),
        height: mix(32, geometry.height),
        "--timeline-progress": p,
        "--timeline-track-height": `${mix(4, geometry.track)}px`,
        "--timeline-radius": `${mix(2, 8)}px`,
        "--timeline-marker-height": `${mix(36, geometry.track + 24)}px`,
        "--timeline-label-offset": `${mix(32, geometry.track / 2 + 20)}px`,
      });
    };
    const measure = () => {
      const root = host.getBoundingClientRect(),
        row = controls.getBoundingClientRect(),
        gap = placeholder.getBoundingClientRect();
      const y = Number(gsap.getProperty(controls, "y")) || 0;
      Object.assign(geometry, {
        left: gap.left - root.left,
        top: gap.top - root.top - y,
        width: gap.width,
        fullLeft: row.left - root.left,
        fullWidth: row.width,
        // Idle rail and buttons share a center. Reserve enough travel for the
        // expanded half-height plus the existing 8px gap, at every viewport.
        lift: row.height / 2 + geometry.track / 2 + 8,
        height: 44,
        track: 28,
      });
      render();
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(host);
    observer.observe(placeholder);
    if (host.parentElement) observer.observe(host.parentElement);
    const tween = gsap.to(state.current, {
      progress: expanded ? 1 : 0,
      duration: animated
        ? 0.3 * Math.abs((expanded ? 1 : 0) - state.current.progress)
        : 0,
      // Apply the forward curve toward either target. Playing its timeline
      // backward would start exit at the flat settling tail and feel delayed.
      ease: timelineEase,
      onUpdate: render,
    });
    return () => {
      tween.kill();
      observer.disconnect();
    };
  }, [overlay, dock, slot, timeline, expanded, animated]);
}

export function useVideoReducedMotion(force = false) {
  const [reduced, setReduced] = useState(true);
  useEffect(() => {
    const query = matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return force || reduced;
}

const locks = new WeakMap<Document, { count: number; overflow: string }>();
function lockScroll(doc: Document) {
  const entry = locks.get(doc) ?? {
    count: 0,
    overflow: doc.documentElement.style.overflow,
  };
  entry.count++;
  locks.set(doc, entry);
  doc.documentElement.style.overflow = "hidden";
  return () => {
    if (--entry.count === 0) {
      doc.documentElement.style.overflow = entry.overflow;
      locks.delete(doc);
    }
  };
}

/** GSAP layout interpolation: animate geometry, never scale readable controls.
 * A manual top-layer popover keeps the same video node above transformed ancestors.
 */
export function useVideoExpansion(
  frame: RefObject<HTMLDivElement | null>,
  placeholder: RefObject<HTMLDivElement | null>,
  expanded: boolean,
  animated: boolean,
  close: () => void,
) {
  const animation = useRef<gsap.core.Tween | null>(null);
  const expandedRef = useRef(false);
  const closeRef = useRef(close);
  closeRef.current = close;
  const savedFocus = useRef<HTMLElement | null>(null);
  const release = useRef<(() => void) | null>(null);

  useLayoutEffect(() => {
    const el = frame.current;
    const slot = placeholder.current;
    if (!el || !slot) return;
    const wasExpanded = expandedRef.current;
    if (!expanded && !wasExpanded && !animation.current) return;
    const rect = el.getBoundingClientRect(); // Capture before cancelling an interrupted tween.
    animation.current?.kill();
    expandedRef.current = expanded;
    if (expanded && !wasExpanded) {
      // A reversal still owns the original focus and scroll lock.
      if (!release.current) {
        savedFocus.current = el.ownerDocument.activeElement as HTMLElement;
        release.current = lockScroll(el.ownerDocument);
      }
      try {
        el.showPopover?.();
      } catch {
        /* fixed-position fallback */
      }
    }
    const inline = slot.getBoundingClientRect();
    const target = expanded
      ? {
          x: 0,
          y: 0,
          width: window.innerWidth,
          height: window.innerHeight,
          borderRadius: 0,
          "--video-backdrop": 1,
        }
      : {
          x: inline.left,
          y: inline.top,
          width: inline.width,
          height: inline.height,
          borderRadius: 20,
          "--video-backdrop": 0,
        };
    gsap.set(el, {
      position: "fixed",
      inset: "auto",
      margin: 0,
      zIndex: 1000,
    });
    // Set the inset shorthand first: rendering it in the same GSAP set as
    // left/top can reset those longhands to auto and jump to the origin.
    gsap.set(el, {
      left: 0,
      top: 0,
      x: rect.left,
      y: rect.top,
      force3D: true,
      width: rect.width,
      height: rect.height,
    });
    const finish = () => {
      animation.current = null;
      if (!expandedRef.current) {
        try {
          el.hidePopover?.();
        } catch {
          /* no top-layer API */
        }
        gsap.set(el, {
          clearProps:
            "position,inset,margin,zIndex,left,top,width,height,transform,borderRadius,--video-backdrop",
        });
        release.current?.();
        release.current = null;
        savedFocus.current?.focus({ preventScroll: true });
      }
    };
    if (animated)
      animation.current = gsap.to(el, {
        ...target,
        duration: videoFullscreenMotion.duration,
        ease: videoFullscreenMotion.ease,
        overwrite: true,
        onComplete: finish,
      });
    else {
      gsap.set(el, target);
      finish();
    }
  }, [expanded, animated, frame, placeholder]);

  useEffect(() => {
    const el = frame.current;
    if (!el || !expanded) return;
    const doc = el.ownerDocument;
    // Inert siblings along the ancestor path without reparenting the video.
    const inert: { el: HTMLElement; value: boolean }[] = [];
    let branch: HTMLElement = el;
    while (branch.parentElement) {
      for (const sibling of Array.from(branch.parentElement.children)) {
        if (sibling !== branch && sibling instanceof HTMLElement) {
          inert.push({ el: sibling, value: sibling.inert });
          sibling.inert = true;
        }
      }
      branch = branch.parentElement;
      if (branch === doc.body) break;
    }
    const key = (event: KeyboardEvent) => {
      if (event.defaultPrevented) return;
      if (event.key === "Escape") {
        event.preventDefault();
        closeRef.current();
      }
      if (event.key === "Tab") {
        const nodes = Array.from(
          el.querySelectorAll<HTMLElement>(
            'button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]',
          ),
        ).filter(
          (node) =>
            !node.closest("[inert]") && node.getClientRects().length > 0,
        );
        const first = nodes[0],
          last = nodes.at(-1);
        if (
          event.shiftKey &&
          (doc.activeElement === first || doc.activeElement === el)
        ) {
          event.preventDefault();
          last?.focus();
        } else if (!event.shiftKey && doc.activeElement === last) {
          event.preventDefault();
          first?.focus();
        }
      }
    };
    const resize = () => {
      animation.current?.kill();
      animation.current = null;
      gsap.set(el, {
        x: 0,
        y: 0,
        width: window.innerWidth,
        height: window.innerHeight,
        borderRadius: 0,
        "--video-backdrop": 1,
      });
    };
    el.focus({ preventScroll: true });
    doc.addEventListener("keydown", key);
    window.addEventListener("resize", resize);
    return () => {
      doc.removeEventListener("keydown", key);
      window.removeEventListener("resize", resize);
      inert.forEach(({ el, value }) => {
        el.inert = value;
      });
    };
  }, [expanded, frame]);
  useEffect(
    () => () => {
      animation.current?.kill();
      release.current?.();
      release.current = null;
      savedFocus.current?.focus({ preventScroll: true });
    },
    [],
  );
}

"use client";
import { useState, useSyncExternalStore } from "react";
import { useVideoPlayer, useVideoState } from "./video-player-context";
import { detectVideoFormat } from "./video-player-utils";
import type { VideoFormat } from "./video-player-types";

const number = (value: number | null | undefined, unit = "", decimals = 1) =>
  value == null || !Number.isFinite(value)
    ? "N/A"
    : `${value.toFixed(decimals)}${unit}`;
export default function PlaybackDiagnostics({
  src,
  format,
}: {
  src: string;
  format?: VideoFormat;
}) {
  const [open, setOpen] = useState(true);
  return (
    <section className="mt-4 rounded-xl border border-border bg-background text-foreground">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen(!open)}
        className="flex min-h-11 w-full items-center justify-between px-4 text-left text-xs font-medium focus-visible:outline-2 focus-visible:outline-ring"
      >
        Streaming diagnostics
        <span className="text-muted-foreground">{open ? "Hide" : "Show"}</span>
      </button>
      {open && <Metrics format={detectVideoFormat(src, format)} />}
    </section>
  );
}
function Metrics({ format }: { format: VideoFormat }) {
  const { store } = useVideoPlayer();
  const metrics = useSyncExternalStore(
    store.subscribeDiagnostics,
    store.getDiagnostics,
    store.getDiagnostics,
  );
  const engine = useVideoState((s) => s.engine),
    quality = useVideoState((s) => s.selectedQuality),
    rate = useVideoState((s) => s.rate),
    capabilities = useVideoState((s) => s.capabilities);
  const [copied, setCopied] = useState("");
  const s = metrics.stats;
  const fields = [
    ["Engine / format", `${engine ?? "Loading"} / ${format.toUpperCase()}`],
    ["Resolution", s?.width && s.height ? `${s.width} × ${s.height}` : "N/A"],
    [
      "Bandwidth estimate",
      number(
        s?.estimatedBandwidth == null ? null : s.estimatedBandwidth / 1e6,
        " Mbps",
      ),
    ],
    [
      "Rendition bitrate",
      number(
        s?.variantBitrate == null ? null : s.variantBitrate / 1e6,
        " Mbps",
      ),
    ],
    [
      "Buffer ahead / behind",
      `${number(metrics.bufferAhead, "s")} / ${number(metrics.bufferBehind, "s")}`,
    ],
    ["Rebuffers", String(metrics.stalls)],
    ["Buffering time", number(store.bufferingSeconds(), "s")],
    ["Load latency", number(s?.loadLatency, "s")],
    ["First play latency", number(metrics.startupSeconds, "s")],
    ["Dropped frames", number(s?.droppedFrames, "", 0)],
    ["Playback rate", `${rate}×`],
    [
      "ABR",
      capabilities.quality
        ? quality === "auto"
          ? "Enabled"
          : "Manual"
        : "N/A",
    ],
  ];
  return (
    <div className="border-t border-border px-4 pb-4">
      <dl className="grid grid-cols-2 gap-x-5 gap-y-4 py-4 @min-[640px]:grid-cols-3">
        {fields.map(([label, value]) => (
          <div key={label}>
            <dt className="text-[10px] text-muted-foreground">{label}</dt>
            <dd className="mt-1 font-mono text-xs tabular-nums">{value}</dd>
          </div>
        ))}
      </dl>
      <p className="mb-3 text-[11px] text-muted-foreground">
        Requested quality and active rendition may differ while buffered
        segments finish. N/A means unavailable. First play latency includes time
        waiting for user input.
      </p>
      {metrics.latestError && (
        <p className="mb-3 text-xs">
          Latest error: {metrics.latestError.category} /{" "}
          {metrics.latestError.code} · {metrics.latestError.message}
        </p>
      )}
      <ol
        aria-label="Playback event timeline"
        className="max-h-40 overflow-auto rounded-lg bg-muted p-3 font-mono text-[10px] leading-5"
      >
        {metrics.events.map((event, i) => (
          <li key={`${event.at}-${i}`}>
            <span className="mr-3 text-muted-foreground">
              {number(event.at / 1000, "s")}
            </span>
            {event.event}
            {event.detail && ` · ${event.detail}`}
          </li>
        ))}
      </ol>
      <div className="mt-3 flex items-center gap-3">
        <button
          type="button"
          className="min-h-11 rounded-lg border border-border px-3 text-xs focus-visible:outline-2 focus-visible:outline-ring"
          onClick={() => {
            void navigator.clipboard?.writeText(store.exportDiagnostics()).then(
              () => setCopied("Copied"),
              () => setCopied("Clipboard unavailable"),
            );
            if (!navigator.clipboard) setCopied("Clipboard unavailable");
          }}
        >
          Copy diagnostics
        </button>
        <span role="status" className="text-xs text-muted-foreground">
          {copied}
        </span>
      </div>
    </div>
  );
}

import type {
  PlayerAdapter,
  PlayerEvent,
  PlaybackStats,
  VideoSource,
  VideoTrack,
} from "./video-player-types";
import { detectVideoFormat, finite, readRanges } from "./video-player-utils";

export class NativeAdapter implements PlayerAdapter {
  readonly engine = "native" as const;
  readonly capabilities = {
    quality: false,
    audio: false,
    captions: true,
    drm: false,
  };
  private cancelLoad?: () => void;
  constructor(
    private video: HTMLVideoElement,
    private emit: (event: PlayerEvent) => void,
  ) {}
  load(source: VideoSource, startTime?: number): Promise<void> {
    const type = detectVideoFormat(source.src, source.type);
    if (
      source.drm ||
      type === "dash" ||
      (type === "hls" &&
        !this.video.canPlayType("application/vnd.apple.mpegurl"))
    ) {
      return Promise.reject(
        new DOMException("Unsupported source", "NotSupportedError"),
      );
    }
    this.emit({ type: "loading" });
    return new Promise((resolve, reject) => {
      const cleanup = () => {
        this.video.removeEventListener("loadedmetadata", ready);
        this.video.removeEventListener("error", fail);
        clearTimeout(timeout);
        this.cancelLoad = undefined;
      };
      const ready = () => {
        cleanup();
        if (startTime && Number.isFinite(this.video.duration))
          this.video.currentTime = Math.min(startTime, this.video.duration);
        this.emit({ type: "manifest" });
        resolve();
      };
      const fail = () => {
        cleanup();
        reject({ category: 3, code: this.video.error?.code });
      };
      const timeout = setTimeout(() => {
        cleanup();
        reject({ category: 1 });
      }, 30000);
      this.cancelLoad = () => {
        cleanup();
        reject(new DOMException("Cancelled", "AbortError"));
      };
      this.video.addEventListener("loadedmetadata", ready);
      this.video.addEventListener("error", fail);
      this.video.src = source.src;
      this.video.load();
    });
  }
  getQualities() {
    return [];
  }
  setQuality() {}
  getAudioTracks() {
    return [];
  }
  setAudioTrack() {}
  getTextTracks(): VideoTrack[] {
    return Array.from(this.video.textTracks).map((t, i) => ({
      id: String(i),
      language: t.language,
      label: t.label || t.language || `Track ${i + 1}`,
      active: t.mode === "showing",
    }));
  }
  setTextTrack(id: string) {
    Array.from(this.video.textTracks).forEach((t, i) => {
      t.mode = String(i) === id ? "showing" : "disabled";
    });
    this.emit({ type: "tracks" });
  }
  getStats(): PlaybackStats {
    return {
      width: this.video.videoWidth || null,
      height: this.video.videoHeight || null,
      estimatedBandwidth: null,
      variantBitrate: null,
      loadLatency: null,
      droppedFrames: finite(
        this.video.getVideoPlaybackQuality?.().droppedVideoFrames,
      ),
    };
  }
  getSeekRange() {
    const ranges = readRanges(this.video.seekable);
    return {
      start: ranges[0]?.[0] ?? 0,
      end: ranges.at(-1)?.[1] ?? 0,
      live: this.video.duration === Infinity,
    };
  }
  destroy() {
    this.cancelLoad?.();
    this.video.pause();
    this.video.removeAttribute("src");
    this.video.load();
  }
}

import shaka from "shaka-player";
import type {
  PlayerAdapter,
  PlayerEvent,
  VideoSource,
} from "./video-player-types";
import { finite, normalizeQualities, playerError } from "./video-player-utils";

/** Imported only after mount and only for the selected engine. No Shaka UI bundle. */
export class ShakaAdapter implements PlayerAdapter {
  readonly engine = "shaka" as const;
  readonly capabilities = {
    quality: true,
    audio: true,
    captions: true,
    drm: true,
  };
  private player: shaka.Player;
  private destroyed = false;
  constructor(
    private video: HTMLVideoElement,
    private emit: (event: PlayerEvent) => void,
  ) {
    shaka.polyfill.installAll();
    if (!shaka.Player.isBrowserSupported())
      throw new DOMException("Unsupported browser", "NotSupportedError");
    this.player = new shaka.Player();
    this.player.addEventListener("error", (event) => {
      const detail = (event as CustomEvent<shaka.util.Error>).detail;
      emit({
        type: "error",
        error: playerError(
          detail,
          detail.severity === shaka.util.Error.Severity.CRITICAL,
        ),
      });
    });
    this.player.addEventListener("buffering", (event) =>
      emit({
        type: "buffering",
        buffering: (event as unknown as { buffering: boolean }).buffering,
      }),
    );
    for (const name of ["adaptation", "variantchanged"])
      this.player.addEventListener(name, () => emit({ type: "quality" }));
    for (const name of [
      "trackschanged",
      "textchanged",
      "texttrackvisibility",
      "audiochanged",
    ])
      this.player.addEventListener(name, () => emit({ type: "tracks" }));
    this.player.addEventListener("retry", () => emit({ type: "recovery" }));
  }
  async load(source: VideoSource, startTime?: number) {
    this.emit({ type: "loading" });
    await this.player.attach(this.video);
    if (this.destroyed) return;
    const retry = {
      maxAttempts: 3,
      baseDelay: 1000,
      backoffFactor: 2,
      timeout: 20000,
    };
    this.player.configure({
      streaming: {
        bufferingGoal: 30,
        rebufferingGoal: 2,
        bufferBehind: 30,
        retryParameters: retry,
      },
      manifest: { retryParameters: retry },
      drm: {
        ...source.drm,
        retryParameters: { ...retry, ...source.drm?.retryParameters },
      },
    });
    await this.player.load(source.src, startTime);
    if (!this.destroyed) this.emit({ type: "manifest" });
  }
  getQualities() {
    const tracks = this.player.getVariantTracks();
    const active = tracks.find((t) => t.active);
    // Do not accidentally change language/audio role while selecting a resolution.
    return normalizeQualities(
      tracks
        .filter(
          (t) =>
            !active ||
            (t.language === active.language && t.audioId === active.audioId),
        )
        .map((t) => ({
          id: String(t.id),
          label: `${t.height ? `${t.height}p` : "Audio"} · ${(t.bandwidth / 1e6).toFixed(1)} Mbps`,
          width: t.width ?? 0,
          height: t.height ?? 0,
          bitrate: t.bandwidth,
          active: t.active,
        })),
    );
  }
  setQuality(id: string) {
    if (id === "auto") {
      this.player.configure({ abr: { enabled: true } });
      return;
    }
    const track = this.player
      .getVariantTracks()
      .find((t) => String(t.id) === id);
    if (!track) return;
    this.player.configure({ abr: { enabled: false } });
    this.player.selectVariantTrack(track, false);
  }
  getAudioTracks() {
    return this.player.getAudioTracks().map((t) => ({
      id: String(t.id),
      label: t.label || t.language || `Audio ${t.id}`,
      language: t.language,
      active: t.active,
    }));
  }
  setAudioTrack(id: string) {
    const track = this.player.getAudioTracks().find((t) => String(t.id) === id);
    if (track) this.player.selectAudioTrack(track);
  }
  getTextTracks() {
    return this.player.getTextTracks().map((t) => ({
      id: String(t.id),
      label: t.label || t.language || `Track ${t.id}`,
      language: t.language,
      active: t.active,
    }));
  }
  setTextTrack(id: string) {
    const track = this.player.getTextTracks().find((t) => String(t.id) === id);
    this.player.selectTextTrack(id === "off" ? null : track);
  }
  getSeekRange() {
    return { ...this.player.seekRange(), live: this.player.isLive() };
  }
  getStats() {
    const s = this.player.getStats();
    return {
      width: finite(this.video.videoWidth),
      height: finite(this.video.videoHeight),
      estimatedBandwidth: finite(s.estimatedBandwidth),
      variantBitrate: finite(s.streamBandwidth),
      droppedFrames: finite(s.droppedFrames),
      loadLatency: finite(s.loadLatency),
    };
  }
  async destroy() {
    this.destroyed = true;
    await this.player.destroy();
  }
}

import Hls from "hls.js";
import type {
  PlayerAdapter,
  PlayerEvent,
  VideoSource,
} from "./video-player-types";
import { NativeAdapter } from "./video-player-native";
import { finite, normalizeQualities, playerError } from "./video-player-utils";

export function createHlsAdapter(
  video: HTMLVideoElement,
  emit: (event: PlayerEvent) => void,
): PlayerAdapter {
  if (Hls.isSupported()) return new HlsAdapter(video, emit);
  if (video.canPlayType("application/vnd.apple.mpegurl"))
    return new NativeAdapter(video, emit);
  throw new DOMException("HLS is unavailable", "NotSupportedError");
}
class HlsAdapter implements PlayerAdapter {
  readonly engine = "hls" as const;
  readonly capabilities = {
    quality: true,
    audio: true,
    captions: true,
    drm: false,
  };
  private hls: Hls;
  private recoveries = 0;
  private timer?: ReturnType<typeof setTimeout>;
  private cancelLoad?: () => void;
  private latency: number | null = null;
  constructor(
    private video: HTMLVideoElement,
    private emit: (event: PlayerEvent) => void,
  ) {
    this.hls = new Hls({
      maxBufferLength: 30,
      backBufferLength: 30,
      autoStartLoad: false,
    });
    this.hls.on(Hls.Events.LEVEL_SWITCHED, () => emit({ type: "quality" }));
    for (const name of [
      Hls.Events.AUDIO_TRACKS_UPDATED,
      Hls.Events.AUDIO_TRACK_SWITCHED,
      Hls.Events.SUBTITLE_TRACKS_UPDATED,
      Hls.Events.SUBTITLE_TRACK_SWITCH,
    ])
      this.hls.on(name, () => emit({ type: "tracks" }));
    this.hls.on(Hls.Events.ERROR, (_, data) => {
      const error = playerError(
        { category: data.type === Hls.ErrorTypes.NETWORK_ERROR ? 1 : 3 },
        data.fatal,
      );
      if (
        data.fatal &&
        this.recoveries < 2 &&
        [Hls.ErrorTypes.NETWORK_ERROR, Hls.ErrorTypes.MEDIA_ERROR].includes(
          data.type,
        )
      ) {
        this.recoveries++;
        emit({ type: "error", error: { ...error, fatal: false } });
        clearTimeout(this.timer);
        this.timer = setTimeout(
          () => {
            emit({ type: "recovery" });
            if (data.type === Hls.ErrorTypes.NETWORK_ERROR)
              this.hls.startLoad();
            else this.hls.recoverMediaError();
          },
          1000 * 2 ** (this.recoveries - 1),
        );
      } else emit({ type: "error", error });
    });
  }
  load(source: VideoSource, startTime?: number): Promise<void> {
    this.emit({ type: "loading" });
    const start = performance.now();
    return new Promise((resolve, reject) => {
      const cleanup = () => {
        clearTimeout(timeout);
        this.hls.off(Hls.Events.MANIFEST_PARSED, ready);
        this.hls.off(Hls.Events.ERROR, fail);
        this.cancelLoad = undefined;
      };
      const ready = () => {
        cleanup();
        this.latency = (performance.now() - start) / 1000;
        this.emit({ type: "manifest" });
        this.hls.startLoad(startTime ?? -1);
        resolve();
      };
      const fail = (_: unknown, data: { fatal: boolean }) => {
        if (data.fatal && this.recoveries >= 2) {
          cleanup();
          reject({ category: 1 });
        }
      };
      const timeout = setTimeout(() => {
        cleanup();
        reject({ category: 1 });
      }, 45000);
      this.cancelLoad = () => {
        cleanup();
        reject(new DOMException("Cancelled", "AbortError"));
      };
      this.hls.on(Hls.Events.MANIFEST_PARSED, ready);
      this.hls.on(Hls.Events.ERROR, fail);
      this.hls.attachMedia(this.video);
      this.hls.loadSource(source.src);
    });
  }
  getQualities() {
    return normalizeQualities(
      this.hls.levels.map((l, i) => ({
        id: String(i),
        label: `${l.height}p · ${(l.bitrate / 1e6).toFixed(1)} Mbps`,
        width: l.width,
        height: l.height,
        bitrate: l.bitrate,
        active: this.hls.currentLevel === i,
      })),
    );
  }
  setQuality(id: string) {
    this.hls.nextLevel = id === "auto" ? -1 : Number(id);
  }
  getAudioTracks() {
    return this.hls.audioTracks.map((t, i) => ({
      id: String(i),
      label: t.name || t.lang || `Audio ${i + 1}`,
      language: t.lang ?? "",
      active: this.hls.audioTrack === i,
    }));
  }
  setAudioTrack(id: string) {
    this.hls.audioTrack = Number(id);
  }
  getTextTracks() {
    return this.hls.subtitleTracks.map((t, i) => ({
      id: String(i),
      label: t.name || t.lang || `Track ${i + 1}`,
      language: t.lang ?? "",
      active: this.hls.subtitleTrack === i && this.hls.subtitleDisplay,
    }));
  }
  setTextTrack(id: string) {
    this.hls.subtitleTrack = id === "off" ? -1 : Number(id);
    this.hls.subtitleDisplay = id !== "off";
  }
  getSeekRange() {
    const ranges = this.video.seekable;
    return {
      start: ranges.length ? ranges.start(0) : 0,
      end: ranges.length ? ranges.end(ranges.length - 1) : 0,
      live: this.hls.levels[this.hls.currentLevel]?.details?.live ?? false,
    };
  }
  getStats() {
    return {
      width: this.video.videoWidth || null,
      height: this.video.videoHeight || null,
      estimatedBandwidth: finite(this.hls.bandwidthEstimate),
      variantBitrate: finite(this.hls.levels[this.hls.currentLevel]?.bitrate),
      droppedFrames: finite(
        this.video.getVideoPlaybackQuality?.().droppedVideoFrames,
      ),
      loadLatency: this.latency,
    };
  }
  destroy() {
    clearTimeout(this.timer);
    this.cancelLoad?.();
    this.hls.destroy();
    this.video.removeAttribute("src");
    this.video.load();
  }
}
